1	// Acceptance test for the change request:
2	//   "I do not want to type one figure for an invoice. Let me list the things I am charging for.
3	//    For each one give a description, how many, and the price each. Work out the total for me."
4	//
5	// An invoice is no longer a single figure: it is a LIST of the things being charged for. Opening an
6	// invoice (invoice-open-<id>, from the project's invoice list) is a navigation to that invoice's own
7	// detail page (invoice-detail-page) — a child route, not a flag. The detail page shows the invoice's
8	// line items in a table (invoice-lineitems-table); each row (lineitem-row-<id>) gives a DESCRIPTION
9	// (lineitem-description), HOW MANY (lineitem-qty), the PRICE EACH (lineitem-unitprice) and the line's
10	// own AMOUNT (lineitem-amount), which is "how many" × "price each". The invoice's total is WORKED OUT
11	// for the user (invoice-amount) as the sum of its line amounts — never typed.
12	//
13	// A new line item is added with the line-item form (lineitem-form): a description, a quantity, the
14	// unit that quantity is in and a unit price (lineitem-form-description / -qty / -unit / -unitprice,
15	// submitted with lineitem-form-submit). Each line also shows that unit on its own row (lineitem-unit).
16	// A line item must describe a real charge — a missing description, or a quantity or price that is not
17	// more than zero, is rejected with a visible error (lineitem-form-error) and nothing is added. A
18	// valid line item joins the list, its amount is worked out, the total grows to match, and it all
19	// survives a fresh load from the server.
20	//
21	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
22	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId } and an
23	// invoice honours { id, projectId, status, lineItems } where each line item is
24	// { id, description, qty, unit, unitPrice } (seeded by its explicit id). This change surfaces no
25	// audit records, so there is nothing to
26	// assert on the audit channel.
27	import { test, expect, type Page, type Locator } from '@playwright/test';
28	import { resetAndSeed } from '../support/seed';
29	
30	const lineItemRows = (page: Page) => page.locator('[data-testid^="lineitem-row-"]');
31	
32	// Locate a line item row by the DESCRIPTION it carries, rather than by a server-assigned id (line
33	// item ids are not seed-controlled). Descriptions in each test are chosen distinct — none a substring
34	// of another — so this is unambiguous. Mirrors how project-invoices.spec.ts finds a freshly added row
35	// by the value it shows.
36	const rowByDescription = (page: Page, description: string): Locator =>
37	  lineItemRows(page).filter({
38	    has: page.getByTestId('lineitem-description').getByText(description, { exact: true }),
39	  });
40	
41	// The invoice's worked-out total lives on its detail page. Scope to the detail page so the match is
42	// the invoice total and not something else named the same elsewhere.
43	const invoiceTotal = (page: Page): Locator =>
44	  page.getByTestId('invoice-detail-page').getByTestId('invoice-amount');
45	
46	// A quantity is a bare count; a price, a line amount or the total may be rendered as money ($300.00)
47	// or bare (300). Assert the figure it carries is PRESENT, so the test binds to the value and not to
48	// one presentation. Figures in each test are chosen so no value is a substring of another.
49	async function expectValue(cell: Locator, n: number): Promise<void> {
50	  await expect(cell).toContainText(String(n));
51	}
52	
53	async function gotoInvoice(page: Page, id: number): Promise<void> {
54	  await page.goto(`/invoices/${id}`);
55	  await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
56	}
